{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Codeine, the closest analogue, has reported human oral bioavailability of 40–70%, directly supporting F ≥ 20% for this morphinan-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Morphine, a close structural relative, shows absolute oral bioavailability of 32% after immediate-release tablets, which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Noscapine, another morphinan alkaloid, has an absolute oral bioavailability of 30% in humans, supporting the high-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Samidorphan, a structurally related opioid modulator, has an absolute oral bioavailability of 69% in healthy volunteers, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Ketobemidone, a related opioid, has a mean absolute oral bioavailability of 34%, again above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a morphinan-like alkaloid with favorable physicochemical properties. The closest experimental analogues—codeine, morphine, noscapine, samidorphan, and ketobemidone—all show human absolute oral bioavailability at or above 20%, mostly in the 30–70% range. Despite moderate Morgan similarities, the consistent direction across multiple related structures supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The impact of the enol ether/ketone and additional methoxy/phenol substitution on first-pass metabolism is not directly measured.",
    "The very polar glucuronide analogue M6G has poor oral bioavailability, but its low transferability limits its relevance to this query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

